{"implementation":"import math
from numbers import Real


def _number(value, name):
    if isinstance(value, bool) or not isinstance(value, Real):
        raise ValueError(f"{name} must be a number")
    value = float(value)
    if not math.isfinite(value):
        raise ValueError(f"{name} must be finite")
    return value


def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "threshold" not in case or "calls" not in case:
        raise ValueError("missing required case field")

    threshold = _number(case["threshold"], "threshold")
    calls = case["calls"]
    if not isinstance(calls, list):
        raise ValueError("calls must be an array")

    accepted_call_ids = []
    diagnostics = []

    for call in calls:
        if not isinstance(call, dict):
            raise ValueError("each call must be an object")
        required = (
            "call_id",
            "loss_without_call",
            "loss_with_call",
            "prediction_tokens",
            "parseable",
        )
        if any(field not in call for field in required):
            raise ValueError("missing required call field")

        call_id = call["call_id"]
        if not isinstance(call_id, str):
            raise ValueError("call_id must be a string")
        loss_without = _number(call["loss_without_call"], "loss_without_call")
        loss_with = _number(call["loss_with_call"], "loss_with_call")
        prediction_tokens = _number(call["prediction_tokens"], "prediction_tokens")
        if prediction_tokens < 0:
            raise ValueError("prediction_tokens must be nonnegative")
        if not isinstance(call["parseable"], bool):
            raise ValueError("parseable must be boolean")

        normalized_gain = (loss_without - loss_with) / max(1.0, prediction_tokens)
        accepted = call["parseable"] and normalized_gain >= threshold
        rounded_gain = round(normalized_gain, 6)
        diagnostics.append({
            "accepted": accepted,
            "call_id": call_id,
            "normalized_gain": rounded_gain,
        })
        if accepted:
            accepted_call_ids.append(call_id)

    return {
        "accepted_call_ids": accepted_call_ids,
        "diagnostics": diagnostics,
    }
